  const setUserField=(id,field,val)=>onUpdateUsers(users.map(x=>x.id===id?{...x,[field]:val}:x));
  const roleLabel=(r)=>r==="directeur"?"Directeur":r==="chef_service"?"Chef de service":r==="coordinateur_site"?"Coordinateur":"Éducateur";
